// Select restricts the returned Lead fields.
func (query LeadQuery) Select(fields ...LeadField) LeadQuery {
	query.projection = make([]string, len(fields))
	for index := range fields {
		query.projection[index] = fields[index].key
	}
	return query
}

// Page selects the first bounded page. Runtime rejects deep offset pagination;
// use After with the last observed record ID for every following page.
func (query LeadQuery) Page(number, size int) LeadQuery {
	query.limit = queryPageLimit(number, size)
	return query
}

// After selects the next bounded page using Runtime's stable ID cursor.
func (query LeadQuery) After(id schema.LeadID, size int) LeadQuery {
